// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.wakewordimport com.roshan.persona.voice.audio.AudioChunk/** * NOUS — Wake word detection result. * * Returned by [WakeWordDetector.processAudio]. Contains: *   - Whether a wake word was detected (with confidence) *   - Which tier detected it (hardware DSP, software TFLite, or MFCC confirmation) *   - The audio chunk that triggered the detection (for speaker pre-check) *   - Detection latency (time from wake word end to detection) * * @see <a href="docs/strategy/module-5-strategy-v2.md">§4 Wake Word Detection</a> */data class WakeWordDetection(    /** Whether a wake word was confirmed detected (after 2-stage confirmation). */    val isDetected: Boolean,    /** Detection confidence (0.0-1.0). */    val confidence: Float,    /** Which tier produced this detection. */    val tier: WakeWordTier,    /** Audio chunk that triggered detection (for speaker pre-check). */    val triggeringChunk: AudioChunk?,    /** Recent audio context (2 seconds pre-roll from circular buffer). */    val contextAudio: AudioChunk?,    /** Detection latency in milliseconds (from wake word end to detection). */    val latencyMs: Long,    /** Whether the speaker pre-check passed (if enabled). */    val speakerPreCheckPassed: Boolean? = null,) {    companion object {        /** No detection — audio chunk didn't contain a wake word. */        fun none(): WakeWordDetection = WakeWordDetection(            isDetected = false,            confidence = 0f,            tier = WakeWordTier.NONE,            triggeringChunk = null,            contextAudio = null,            latencyMs = 0L,        )    }}/** * Which tier of the 3-tier wake word architecture produced the detection. * * NOUS uses a cascaded approach for battery efficiency: *   1. Hardware DSP (SoundTriggerManager) — always-on, < 0.5%/hour battery *   2. Software TFLite (OpenWakeWord) — runs on CPU, ~3%/hour battery *   3. MFCC confirmation — 2nd-stage filter, reduces false positives 10x */enum class WakeWordTier(val number: Int, val displayName: String) {    /** No detection. */    NONE(0, "None"),    /** Tier 1: Hardware DSP (Qualcomm Hexagon / MediaTek APU). */    HARDWARE_DSP(1, "Hardware DSP"),    /** Tier 2: Software TFLite (OpenWakeWord, runs on CPU). */    SOFTWARE_TFLITE(2, "Software TFLite"),    /** Tier 3: MFCC confirmation (2nd-stage filter). */    MFCC_CONFIRMATION(3, "MFCC Confirmation"),    /** Final confirmed detection (passed all tiers + speaker pre-check). */    CONFIRMED(4, "Confirmed"),    ;    companion object {        fun fromNumber(number: Int): WakeWordTier? = entries.firstOrNull { it.number == number }    }}/** * Configuration for wake word detection. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§4 Wake Word Detection</a> */data class WakeWordConfig(    /** Wake word phrase (e.g., "Hey NOUS"). */    val phrase: String = DEFAULT_PHRASE,    /** Detection threshold (0.0-1.0). Higher = fewer false positives. */    val threshold: Float = DEFAULT_THRESHOLD,    /** MFCC confirmation threshold (0.0-1.0). */    val mfccThreshold: Float = DEFAULT_MFCC_THRESHOLD,    /** Whether hardware DSP is preferred (false = software only). */    val preferHardware: Boolean = true,    /** Whether speaker pre-check is enabled. */    val speakerPreCheckEnabled: Boolean = false,    /** Owner voice print for speaker pre-check (192-dim ECAPA-TDNN embedding). */    val ownerVoicePrint: FloatArray? = null,    /** Minimum confidence for speaker pre-check (cosine similarity). */    val speakerThreshold: Float = DEFAULT_SPEAKER_THRESHOLD,    /** Cooldown between detections (ms) to prevent rapid re-triggering. */    val cooldownMs: Long = DEFAULT_COOLDOWN_MS,) {    companion object {        /** Default wake word phrase. */        const val DEFAULT_PHRASE = "Hey NOUS"        /** Default TFLite detection threshold. */        const val DEFAULT_THRESHOLD = 0.7f        /** Default MFCC confirmation threshold. */        const val DEFAULT_MFCC_THRESHOLD = 0.6f        /** Default speaker pre-check threshold (cosine similarity). */        const val DEFAULT_SPEAKER_THRESHOLD = 0.7f        /** Default cooldown between detections (3 seconds). */        const val DEFAULT_COOLDOWN_MS = 3_000L    }    override fun equals(other: Any?): Boolean {        if (this === other) return true        if (javaClass != other?.javaClass) return false        val o = other as? WakeWordConfig ?: return false        if (phrase != o.phrase) return false        if (threshold != o.threshold) return false        if (mfccThreshold != o.mfccThreshold) return false        if (preferHardware != o.preferHardware) return false        if (speakerPreCheckEnabled != o.speakerPreCheckEnabled) return false        if (ownerVoicePrint != null) {            if (o.ownerVoicePrint == null) return false            if (!ownerVoicePrint.contentEquals(o.ownerVoicePrint)) return false        } else if (o.ownerVoicePrint != null) return false        if (speakerThreshold != o.speakerThreshold) return false        if (cooldownMs != o.cooldownMs) return false        return true    }    override fun hashCode(): Int {        var result = phrase.hashCode()        result = 31 * result + threshold.hashCode()        result = 31 * result + mfccThreshold.hashCode()        result = 31 * result + preferHardware.hashCode()        result = 31 * result + speakerPreCheckEnabled.hashCode()        result = 31 * result + (ownerVoicePrint?.contentHashCode() ?: 0)        result = 31 * result + speakerThreshold.hashCode()        result = 31 * result + cooldownMs.hashCode()        return result    }}